import {validateCapture,validateCollection,upsertCapture} from './collection-core.js?v=20261027motion';
import {validateStyleProfile,combineProfiles} from './reference-style.js?v=20261027motion';
const $=id=>document.getElementById(id),key='clippilot-collection-v1',styleKey='clippilot-styles-v1';let items=[],styles=[];
const say=t=>$('collection-status').textContent=t;
function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function persist(){localStorage.setItem(key,JSON.stringify({type:'clippilot-collection',version:1,items}));localStorage.setItem(styleKey,JSON.stringify(styles))}
function button(text,fn){const b=document.createElement('button');b.className='secondary';b.textContent=text;b.onclick=()=>{try{fn()}catch(e){say(e.message)}};return b}
function render(){const box=$('collection-list');box.replaceChildren();for(const item of items){const card=document.createElement('article');card.className='collection-card';const title=document.createElement('strong');title.textContent=item.title||'未命名作品';const source=document.createElement('p');source.textContent=`${item.platform} · ${item.creator||'博主待填写'} · 来源身份未核验`;const link=document.createElement('a');link.href=item.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='打开原作品';card.append(title,source,link,button('载入来源与页面文字',()=>{if($('ref-scan').disabled)throw Error('请等待拉片完成');$('ref-creator').value=item.creator;$('ref-source-url').value=item.url;$('collection-text').value=item.visibleText||item.description;$('collection-text').focus();say('来源已载入。请在下方删掉导航、评论等无关文字，再将正文用于分析；参考视频仍需上传。')}),button('删除',()=>{items=items.filter(x=>x.url!==item.url);persist();render()}));box.append(card)}
 const list=$('style-list');list.replaceChildren();styles.forEach((p,i)=>{const card=document.createElement('article');card.className='collection-card';const text=document.createElement('p');text.textContent=`${p.creator} · ${p.sourceName} · ${p.seconds.length} 段参考节奏（非完整风格识别）`;const choose=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.dataset.styleIndex=i;choose.append(check,document.createTextNode('加入同来源多作品统计'));card.append(choose,text,button('用于创意剪辑',()=>document.dispatchEvent(new CustomEvent('reference-style',{detail:p}))),button('删除',()=>{styles.splice(i,1);persist();render()}));list.append(card)});$('collection-count').textContent=`${items.length}/50 份作品 · ${styles.length}/30 份参考节奏`}
try{const saved=localStorage.getItem(key);if(saved)items=validateCollection(JSON.parse(saved));const savedStyles=JSON.parse(localStorage.getItem(styleKey)||'[]');if(!Array.isArray(savedStyles)||savedStyles.length>30)throw Error('风格库格式异常');styles=savedStyles.map(validateStyleProfile)}catch(e){say('保存内容未完整恢复：'+e.message)}render();
$('collection-import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error('采集文件请小于 2MB');const data=JSON.parse(await f.text());if(data.type==='clippilot-collection'){const incoming=validateCollection(data);const savedStyles=data.styles===undefined?[]:data.styles;if(!Array.isArray(savedStyles)||savedStyles.length>30)throw Error('参考节奏库无效');const importedStyles=savedStyles.map(validateStyleProfile);styles=[...importedStyles,...styles].filter((p,i,a)=>a.findIndex(x=>x.url===p.url&&x.creator===p.creator&&x.sourceName===p.sourceName)===i).slice(0,30);for(const item of incoming.reverse())items=upsertCapture(items,item)}else items=upsertCapture(items,validateCapture(data));persist();render();say('作品已入库。采集的是页面文字，不代表已转录或下载视频。')}catch(err){say('导入失败：'+err.message)}finally{e.target.value=''}};
$('collection-save').onclick=()=>download({type:'clippilot-collection',version:1,items,styles},'ClipPilot-作品库.json');
$('collection-use-text').onclick=()=>{const text=$('collection-text').value.trim();if(!text)return say('请先填写或载入正文');$('ref-transcript').value=text;$('ref-transcript').dispatchEvent(new Event('input'));say('正文已填入文案分析；完成视频拉片后点击“更新拉片报告”。')};
document.addEventListener('reference-style',e=>{try{const p=validateStyleProfile(e.detail);styles=[p,...styles.filter(s=>s.url!==p.url||s.sourceName!==p.sourceName||s.creator!==p.creator)].slice(0,30);persist();render()}catch(err){say('参考节奏未保存：'+err.message)}});

$('style-combine').onclick=()=>{try{const selected=[...document.querySelectorAll('[data-style-index]:checked')].map(e=>styles[Number(e.dataset.styleIndex)]);const p=combineProfiles(selected);document.dispatchEvent(new CustomEvent('reference-style',{detail:p}));say('已按同来源多份作品统计节奏并用于创意剪辑；未自动识别完整风格。')}catch(e){say(e.message)}};
